insert into jj_collect.catalog(id,data) values('nu-301','{"id": "nu-301", "number": 301, "name_es": "Jesús · el haori de Tanjiro", "name_en": "Jesús · Tanjiro’s Haori", "character": "jesus", "theme": "fantasia", "tags": ["kimetsu-no-yaiba", "tanjiro"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Me gusta empezar estas aventuras con algo sencillo: una historia que pueda compartir contigo.", "dedication_en": "I love beginning these adventures with something simple: a story I can share with you.", "art": 0, "collection": "undecimo-universo"}'::jsonb) on conflict(id) do nothing;
